import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.DBKUV7en.js";const b=JSON.parse('{"title":"1. ハンドドリップで、何が起きているか","description":"","frontmatter":{},"headers":[],"relativePath":"basics/how-drip-works.md","filePath":"basics/how-drip-works.md","lastUpdated":null}'),d={name:"basics/how-drip-works.md"};function o(s,a,n,l,p,h){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_1-ハンドドリップで、何が起きているか" tabindex="-1">1. ハンドドリップで、何が起きているか <a class="header-anchor" href="#_1-ハンドドリップで、何が起きているか" aria-label="Permalink to &quot;1. ハンドドリップで、何が起きているか&quot;">​</a></h1><p>ドリップの記事や研究を読むと、「浸漬」とか「透過」とかいう言葉が出てきます。研究によって結果が違うのも、なんだか混乱します。</p><p>この教科書の第2章を読む前に、ハンドドリップの中で何が起きているかを、先に整理しておきます。抽出の話の、土台になる回です。</p><h2 id="お湯が粉を通り抜けるか、粉がお湯に浸かるか" tabindex="-1">お湯が粉を通り抜けるか、粉がお湯に浸かるか <a class="header-anchor" href="#お湯が粉を通り抜けるか、粉がお湯に浸かるか" aria-label="Permalink to &quot;お湯が粉を通り抜けるか、粉がお湯に浸かるか&quot;">​</a></h2><p>淹れ方は、大きく2つに分かれます。お湯が粉の層を通り抜ける<strong>透過式</strong>(ハンドドリップ、エスプレッソ)と、粉をお湯に浸けておく<strong>浸漬</strong>(フレンチプレス、水出し、カッピング)です。透過式は常に新しいお湯が粉に触れ、浸漬は粉とお湯が同じ液の中に入ったままです。</p><p>ハンドドリップは透過式ですが、蒸らしのときはお湯に粉が浸っている時間もあるので、少し浸漬の要素もあります。</p><p>僕が1本目の動画で使ったのは、浸漬式のドリッパーでした。粉15gに93℃のお湯を20秒で230ml入れて、3回かき混ぜて、2分後にスイッチを入れて落としています。同じ「ドリップ」でも、中身はだいぶ違います。</p><h2 id="浸漬では、抽出率が頭打ちになる" tabindex="-1">浸漬では、抽出率が頭打ちになる <a class="header-anchor" href="#浸漬では、抽出率が頭打ちになる" aria-label="Permalink to &quot;浸漬では、抽出率が頭打ちになる&quot;">​</a></h2><p>2021年に、Liang、Chan、Ristenpart らのチームが、浸漬では時間が十分たつと抽出率が<strong>平衡</strong>(つりあいの状態)に達することを示しました。抽出率はおよそ21%で、粉とお湯の比率に関係なくほぼ一定です。一方、濃度は湯と粉の比率にほぼ反比例して、湯を2倍にすると、濃度はほぼ半分になりました。</p><p>挽き目、焙煎度、湯温(80〜99℃)にも、あまり左右されませんでした。平衡に達した場合の話です。浸漬では、比率が濃度を決めて、抽出率は豆と水でほぼ決まります。著者は、浸漬で動かすべきつまみは、まず比率だとまとめています。</p><h2 id="透過式は、そうではない" tabindex="-1">透過式は、そうではない <a class="header-anchor" href="#透過式は、そうではない" aria-label="Permalink to &quot;透過式は、そうではない&quot;">​</a></h2><p>ドリップでは、新しいお湯が次々に粉へ入るので、粉の中の成分とまわりの液との濃度の差が大きいまま続きます。そのため溶け出しが速く進む、と専門家の Scott Rao は説明しています。浸漬は、液が濃くなるにつれて差が小さくなり、進みが遅くなります。</p><p>別の専門家、Hoffmann は、同じ抽出率でも浸漬は透過式より少し薄いコーヒーになる、と話しています。2人の話は合っていますが、どちらも研究ではなく、専門家の意見です。</p><h2 id="粉の層の中で、お湯はどう流れるか" tabindex="-1">粉の層の中で、お湯はどう流れるか <a class="header-anchor" href="#粉の層の中で、お湯はどう流れるか" aria-label="Permalink to &quot;粉の層の中で、お湯はどう流れるか&quot;">​</a></h2><p>ドリップの粉の層を数式のモデルで調べた研究があります(Moroney ら、PLoS ONE、2019)。コーン形のドリッパーでは、水の流れが偏って、場所ごとの抽出に大きなばらつきが出る、という結果でした。ばらつきが大きいと苦味が出ると予想される、と著者は述べています。モデルの推測で、味は測っていません。蒸らしで出るガスの影響も、このモデルには入っていません。このばらつきが、第7回のムラの話につながります。</p><h2 id="研究ごとに方式が違う" tabindex="-1">研究ごとに方式が違う <a class="header-anchor" href="#研究ごとに方式が違う" aria-label="Permalink to &quot;研究ごとに方式が違う&quot;">​</a></h2><p>この教科書では、いろいろな研究を使います。方式が違うので、混ぜて読まないように、先に分けておきます。</p><table tabindex="0"><thead><tr><th>研究</th><th>方式</th></tr></thead><tbody><tr><td>Batali 2020、Frost 2020、Cotter 2021</td><td>透過(業務用のドリップ機)</td></tr><tr><td>Frost 2019(バスケットの形)</td><td>透過</td></tr><tr><td>Liang 2021、Batali 2022、Liang 2024</td><td>浸漬</td></tr><tr><td>Rune 2023</td><td>浸漬(フレンチプレス)</td></tr><tr><td>Lindsey 2024</td><td>浸漬主体(エアロプレス)</td></tr></tbody></table><p>研究の条件は、<a href="/coffee-textbook/appendix/studies">付録</a>にまとめています。</p><h2 id="湯温の結果が、研究で違って見える理由" tabindex="-1">湯温の結果が、研究で違って見える理由 <a class="header-anchor" href="#湯温の結果が、研究で違って見える理由" aria-label="Permalink to &quot;湯温の結果が、研究で違って見える理由&quot;">​</a></h2><p>第6回で見たとおり、2020年(透過)は湯温が味にほぼ効かず、浸漬の研究では湯温も効いていました。理由は3つ考えられます。2020年は温度の範囲が87〜93℃と狭く、浸漬の研究は4℃から92℃と広いこと。2020年は濃度と抽出率をそろえて比べたこと。そして、方式が違うことです。</p><p>2022年の浸漬の研究(Batali ら、Foods)では、平衡まで抽出して、濃度をTDS 2%にそろえ、4℃で飲んでいます。それでも92℃で淹れたものは、苦さ、酸っぱさ、ゴムのような香りが強く、4℃と22℃のものは花の香りが強い傾向でした。産地や焙煎との組み合わせで変わります。熱いお湯は、抽出を速くするだけでなく、取り出す成分の種類も変えているのではないか、と僕は考えています。</p><h2 id="抽出率の計算式は、方式で少し違う" tabindex="-1">抽出率の計算式は、方式で少し違う <a class="header-anchor" href="#抽出率の計算式は、方式で少し違う" aria-label="Permalink to &quot;抽出率の計算式は、方式で少し違う&quot;">​</a></h2><p>Scott Rao の指摘では、浸漬の計算式は、カップに入らなかった粉の中の液まで数えて、抽出率が大きめに出ます。透過式の式は、粉の層の隙間にあった分を数えず、小さめに出ます。なので、透過と浸漬で同じ抽出率20%でも、同じ味とは限らない可能性があります。本人も推測と書いています。</p><h2 id="準備中" tabindex="-1">(準備中...) <a class="header-anchor" href="#準備中" aria-label="Permalink to &quot;(準備中...)&quot;">​</a></h2><p>同じ豆を、ドリップと浸漬で、同じ濃度にそろえて淹れ比べる実験は、予定が決まっていません。手淹れで両方を比べた味の研究は見つかっていないので、やってみる価値はありそうです。</p><h2 id="確かさの一覧" tabindex="-1">確かさの一覧 <a class="header-anchor" href="#確かさの一覧" aria-label="Permalink to &quot;確かさの一覧&quot;">​</a></h2><details class="details custom-block"><summary>表を開く</summary><table tabindex="0"><thead><tr><th>書いたこと</th><th>確かさ</th></tr></thead><tbody><tr><td>浸漬では抽出率が約21%で頭打ちになり、比率が濃度を決める</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Liang ら 2021(原文を確認)</td></tr><tr><td>透過式は、挽き目・流れる速さ・時間で抽出率を動かせる</td><td><span class="stamp stamp-established ignore-header" tabindex="0" data-tip="信頼できる複数の情報源で、言っていることが一致している" aria-label="定説: 信頼できる複数の情報源で、言っていることが一致している">定説</span> 広く使われる説明</td></tr><tr><td>透過式のほうが、溶け出しが速く進む</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 専門家(Rao)の説明。研究は見つかっていない</td></tr><tr><td>同じ抽出率でも、浸漬のほうが薄くなる</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 専門家(Hoffmann)の見方。動画での発言</td></tr><tr><td>コーン形ドリッパーで、水の流れが偏る</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Moroney ら 2019(数式のモデル研究)。味は測っていない</td></tr><tr><td>湯温の結果が違って見える3つの理由</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察</td></tr><tr><td>熱いお湯が、取り出す成分の種類も変える</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察。Batali ら 2022 の結果からの推測</td></tr><tr><td>手淹れで、透過と浸漬を同じ豆・同じ濃度で比べた味の研究</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> 見つかっていない</td></tr></tbody></table></details><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><ul><li>Liang, Chan, Ristenpart (2021) Scientific Reports(浸漬の平衡). <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7994670/" target="_blank" rel="noreferrer">PMC</a></li><li>Batali ら (2022) Foods(水出しとお湯の比較). <a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9407127/" target="_blank" rel="noreferrer">PMC</a></li><li>Moroney ら (2019) PLoS ONE(粉の層の流れのモデル). <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6668809/" target="_blank" rel="noreferrer">PMC</a></li><li>Scott Rao (2017) <a href="https://www.scottrao.com/blog/2017/10/20/immersion-vs-percolation" target="_blank" rel="noreferrer">Immersion vs Percolation</a>(専門家のブログ)</li><li>Hoffmann (2023) <a href="https://www.youtube.com/watch?v=8uGGeV8A-BM" target="_blank" rel="noreferrer">動画</a>(字幕で確認)</li></ul><p>次は、<a href="/coffee-textbook/basics/base-recipe">2. 基準の一杯</a>です。</p>',31)])])}const m=t(d,[["render",o]]);export{b as __pageData,m as default};
